func resourceVertexAIEndpointDeployedModelEncoder(d *schema.ResourceData, meta interface{}, obj map[string]interface{}) (map[string]interface{}, error) {
	req := make(map[string]interface{})
	deployedModel := make(map[string]interface{})
	for key, value := range obj {
		deployedModel[key] = value
	}
	trafficSplit, hasTrafficSplit := deployedModel["trafficSplit"]
	delete(deployedModel, "trafficSplit")
	delete(deployedModel, "endpoint")
	delete(deployedModel, "region")
	delete(deployedModel, "deployedModelId")
	if id, ok := d.GetOk("deployed_model_id"); ok {
		deployedModel["id"] = id
	}
	req["deployedModel"] = deployedModel
	if hasTrafficSplit {
		req["trafficSplit"] = trafficSplit
	}
	return req, nil
}

func resourceVertexAIEndpointDeployedModelDecoder(d *schema.ResourceData, meta interface{}, res map[string]interface{}) (map[string]interface{}, error) {
	deployedModels, ok := res["deployedModels"].([]interface{})
	if !ok {
		return nil, fmt.Errorf("Vertex AI endpoint response did not contain deployedModels")
	}
	deployedModelID := d.Get("deployed_model_id").(string)
	for _, raw := range deployedModels {
		model, ok := raw.(map[string]interface{})
		if !ok {
			continue
		}
		if id, _ := model["id"].(string); id == deployedModelID {
			model["endpoint"] = d.Get("endpoint")
			model["region"] = d.Get("region")
			model["deployedModelId"] = deployedModelID
			model["trafficSplit"] = res["trafficSplit"]
			return model, nil
		}
	}
	return nil, fmt.Errorf("deployed model %q was not found on endpoint %q", deployedModelID, d.Get("endpoint"))
}

